# 窗口内超时项不占资源；存活项按推进同序（有效优先级降序、入队序升序）
# 模拟闸口与取址占用，结果存表后仍按窗口的入队序输出。
outcomes = {}
survivors_window = []
for queued_sid in window:
    entry = capacity_queue[queued_sid]
    if entry[3] <= now_ms:
        outcomes[queued_sid] = (_CAP_TIMEOUT, "截止")
    else:
        survivors_window.append(queued_sid)
for queued_sid in self._rank_queue(survivors_window, now_ms):
    entry = capacity_queue[queued_sid]
    user = entry[0]

    # 等待原因按全局/用户/模板/无池/池故障/地址取首个受阻项；全部
    # 闸口通过且可取址才晋升，晋升占用即时影响后项。
    template_id = self._user_templates.get(user)
    session_limit = (
        self._templates[template_id][4]
        if template_id is not None
        else 0
    )
    if total_count >= self._total:
        result, reason = "等待", "全局"
    elif per_user.get(user, 0) >= self._per:
        result, reason = "等待", "用户"
    elif (
        session_limit
        and per_template.get(template_id, 0) >= session_limit
    ):
        result, reason = "等待", "模板"
    elif pool is None:
        result, reason = "等待", "无池"
    elif self._pool_is_exhausted(_DEFAULT_POOL_ID, now_ms):
        result, reason = "等待", "池故障"
    else:
        static_ip = static_by_user.get(user)
        if static_ip is None:
            # 动态用户：有空闲槽即可取址（具体址不影响后续判定）。
            address_ok = dyn_free > 0
        else:
            # 专属静态址：未被持租方可用，不回落动态址。
            address_ok = not static_held.get(user)
        if not address_ok:
            result, reason = "等待", "地址"
        else:
            if static_ip is None:
                dyn_free -= 1
            else:
                static_held[user] = True
            total_count += 1
            per_user[user] = per_user.get(user, 0) + 1
            if template_id is not None:
                per_template[template_id] = (
                    per_template.get(template_id, 0) + 1
                )
            result, reason = _CAP_PROMOTED, ""
    outcomes[queued_sid] = (result, reason)

for queued_sid in window:
    entry = capacity_queue[queued_sid]
    result, reason = outcomes[queued_sid]
    items.append(
        {
            "会话": queued_sid,
            "用户": entry[0],
            "入队序": entry[4],
            "结果": result,
            "原因": reason,
        }
    )

